#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

int main(int argc, char **argv)
{
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr = NULL;
    long n = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (n > 1000000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    if (n < 2) {
        puts("NONE");
        return 0;
    }
    bool first = true;
    long remaining = n;
    for (long p = 2; p * p <= remaining; ++p) {
        if (remaining % p == 0) {
            int exp = 0;
            while (remaining % p == 0) {
                remaining /= p;
                ++exp;
            }
            if (!first) putchar(' ');
            printf("%ld^%d", p, exp);
            first = false;
        }
    }
    if (remaining > 1) {
        if (!first) putchar(' ');
        printf("%ld^1", remaining);
    }
    putchar('\n');
    return 0;
}
